import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';
import './Auth.css';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const result = await login(email, password);

    if (result.success) {
      toast.success('Login successful!');
      navigate(result.data.role === 'admin' ? '/admin/dashboard' : '/user/dashboard');
    } else {
      toast.error(result.message);
    }
    setLoading(false);
  };

  return (
    <div className="login-wrapper">
      <div className="login-container">

        {/* LEFT SIDE: Blue Branding with 3D Bubbles */}
        <div className="login-branding">
          <div className="brand-content">
            <h1 className="brand-title">WELCOME</h1>
            <h3 className="brand-subtitle">YOUR HEADLINE NAME</h3>
            <p className="brand-desc">
              Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore.
            </p>
          </div>

          {/* 3D Bubbles Decoration */}
          <div className="bubble bubble-1"></div>
          <div className="bubble bubble-2"></div>
          <div className="bubble bubble-3"></div>
        </div>

        {/* RIGHT SIDE: Login Form */}
        <div className="login-form-wrapper">
          <div className="login-card">
            <h2 className="form-title">Sign In</h2>
            <p className="form-subtitle">Lorem ipsum dolor sit amet consectetur adipiscing elit.</p>

            <form onSubmit={handleSubmit}>
              <div className="input-group">
                <label>User Name</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-user"></i>
                  <input 
                    type="email" 
                    value={email} 
                    onChange={(e) => setEmail(e.target.value)} 
                    required 
                    placeholder="Enter your email" 
                  />
                </div>
              </div>

              <div className="input-group">
                <label>Password</label>
                <div className="input-with-icon">
                  <i className="fa-solid fa-lock"></i>
                  <input 
                    type="password" 
                    value={password} 
                    onChange={(e) => setPassword(e.target.value)} 
                    required 
                    placeholder="Enter your password" 
                  />
                  <span className="show-pass-icon">
                    <i className="fa-solid fa-eye-slash"></i>
                  </span>
                </div>
              </div>

              <div className="form-actions">
                <div className="remember-me">
                  <input type="checkbox" id="remember" />
                  <label htmlFor="remember">Remember me</label>
                </div>
                <Link to="#" className="forgot-pass">Forgot Password?</Link>
              </div>

              <button type="submit" className="signin-btn" disabled={loading}>
                {loading ? 'Signing in...' : 'Sign In'}
              </button>

              <div className="divider">or</div>

              <button type="button" className="social-btn">
                Sign in with other
              </button>
            </form>

            <p className="auth-link">
              Don't have an account? <Link to="/register">Sign Up</Link>
            </p>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Login;
